DELETE FROM social_business_config WHERE business_id BETWEEN 92001 AND 92999 OR (user_id = 1 AND business_id = 910001);
DELETE FROM social_connections WHERE business_id BETWEEN 92001 AND 92999 OR (user_id = 1 AND business_id = 910001);
DELETE FROM agency_jobs WHERE location_id BETWEEN 92001 AND 92999;
DELETE FROM business_locations WHERE id BETWEEN 92001 AND 92999;
UPDATE business_locations SET agency_client_id = NULL WHERE user_id = 1 AND agency_client_id BETWEEN 92001 AND 92999;
DELETE FROM agency_clients WHERE id BETWEEN 92001 AND 92999;
DELETE FROM agency_workspaces WHERE user_id = 1 AND name = 'Rivera Growth Partners';
DELETE FROM gbp_grants WHERE user_id = 1 AND google_subject = 'fs-b-agency-subject';
DELETE FROM review_requests WHERE id BETWEEN 92001 AND 92999;
DELETE FROM review_templates WHERE id BETWEEN 92001 AND 92999;
DELETE FROM review_reminder_settings WHERE user_id = 1;
DELETE FROM lsa_leads WHERE lead_id LIKE 'fs-b-%';
DELETE FROM lsa_accounts WHERE id LIKE 'fs-b-%';
DELETE FROM lsa_connections WHERE user_id = 1;
DELETE FROM media_photos WHERE id BETWEEN 92001 AND 92999;
DELETE FROM media_folders WHERE id BETWEEN 92001 AND 92999;

