-- ---- Google profile reviews (synced-style records; review ids are sample ids, not Google resource names)
OVERRIDING SYSTEM VALUE VALUES (92001,1,910001,'fs-b-sample/reviews/92001','Rachel Morgan',5,'Summit replaced our roof after the September hail storm. They walked us through the insurance paperwork, the crew was on time both days and the cleanup was spotless — not a single nail in the driveway.',now() - interval '1 days 3 hours',NULL,NULL,NULL,true,now() - interval '1 days',now() - interval '0 days','Thank you, Rachel! We''re glad the insurance side went smoothly and that the crew left your driveway the way they found it. Enjoy the new roof, and call us anytime. — Sam, Summit Roofing Co.','draft',false);
OVERRIDING SYSTEM VALUE VALUES (92002,1,910001,'fs-b-sample/reviews/92002','Daniel Price',5,'Fast, honest estimate. They told me I only needed a repair, not a whole new roof, which saved me a lot of money. Will use them again.',now() - interval '3 days 3 hours',NULL,NULL,NULL,true,now() - interval '3 days',now() - interval '2 days','Daniel, thank you for trusting us with the repair. We''d always rather fix what needs fixing than sell a roof you don''t need. — Sam, Summit Roofing Co.','draft',false);
OVERRIDING SYSTEM VALUE VALUES (92003,1,910002,'fs-b-sample/reviews/92003','Grace Liu',4,'Good work on our gutters and the new downspouts drain away from the foundation now. Took an extra week to get on the schedule, but worth the wait.',now() - interval '5 days 3 hours',NULL,NULL,NULL,false,now() - interval '5 days',now() - interval '4 days',NULL,'draft',false);
OVERRIDING SYSTEM VALUE VALUES (92004,1,910001,'fs-b-sample/reviews/92004','Michael Torres',5,'Third time using Summit for our rental properties. Consistent quality and they send photos of every step so I don''t have to drive over.',now() - interval '8 days 3 hours','Michael, we appreciate your repeat business! Sending photos is the least we can do when you can''t be on site. See you on the next one. — Sam, Summit Roofing Co.',now() - interval '7 days 1 hour',NULL,false,now() - interval '8 days',now() - interval '7 days',NULL,'posted',false);
OVERRIDING SYSTEM VALUE VALUES (92005,1,910001,'fs-b-sample/reviews/92005','Emily Sanders',3,'The roof looks great, but communication could be better. I had to call twice to find out when the crew was coming back to finish the ridge vent.',now() - interval '11 days 3 hours','Emily, thank you for the honest feedback. You''re right that we should have called you about the return visit. We''ve added a day-before text for every follow-up visit so it doesn''t happen again. — Sam, Summit Roofing Co.',now() - interval '10 days 1 hour','Crew lead: Jake. Follow-up visit was delayed by the Sept 14 storm calls.',false,now() - interval '11 days',now() - interval '10 days',NULL,'posted',false);
OVERRIDING SYSTEM VALUE VALUES (92006,1,910002,'fs-b-sample/reviews/92006','Brian Walsh',5,'Excellent experience from estimate to final inspection. Price was fair and they finished a day early.',now() - interval '14 days 3 hours','Brian, thanks so much! Finishing early is always a good day for us too. — Sam, Summit Roofing Co.',now() - interval '13 days 1 hour',NULL,false,now() - interval '14 days',now() - interval '13 days',NULL,'posted',false);
OVERRIDING SYSTEM VALUE VALUES (92007,1,910001,'fs-b-sample/reviews/92007','Olivia Bennett',5,'Our attic was always hot in summer. Summit added ridge vents and baffles and the difference is huge. Very professional team.',now() - interval '18 days 3 hours','Thank you, Olivia! Ventilation makes a real difference in a Denver summer. Glad you''re feeling it. — Sam, Summit Roofing Co.',now() - interval '17 days 1 hour',NULL,false,now() - interval '18 days',now() - interval '17 days',NULL,'posted',false);
OVERRIDING SYSTEM VALUE VALUES (92008,1,910001,'fs-b-sample/reviews/92008','Steve Kowalski',2,'Roof is fine but they damaged a section of my flower bed with a ladder and it took several calls to get someone to look at it.',now() - interval '23 days 3 hours','Steve, we''re sorry about the flower bed and that it took several calls to get it looked at. Our project manager has reached out to arrange a replacement for the plants. Thank you for telling us. — Sam, Summit Roofing Co.',now() - interval '22 days 1 hour','Replacement plants delivered Sept 21. Customer confirmed.',false,now() - interval '23 days',now() - interval '22 days',NULL,'posted',false);
OVERRIDING SYSTEM VALUE VALUES (92009,1,910002,'fs-b-sample/reviews/92009','Natalie Brooks',5,'Called them about a leak during a storm and they had a tarp on it the same evening. Repair was done two days later. Highly recommend.',now() - interval '27 days 3 hours','Natalie, we''re glad we could get there quickly! Thank you for the kind words. — Sam, Summit Roofing Co.',now() - interval '26 days 1 hour',NULL,false,now() - interval '27 days',now() - interval '26 days',NULL,'posted',false);
OVERRIDING SYSTEM VALUE VALUES (92010,1,910001,'fs-b-sample/reviews/92010','Andrew Fischer',4,'Solid work and a clean job site. Would give 5 stars but the final invoice came a bit later than promised.',now() - interval '33 days 3 hours',NULL,NULL,NULL,false,now() - interval '33 days',now() - interval '32 days',NULL,'draft',false);
OVERRIDING SYSTEM VALUE VALUES (92011,1,910001,'fs-b-sample/reviews/92011','Jessica Reyes',5,'From the first estimate to the final walkthrough everything was explained clearly. The new roof looks fantastic.',now() - interval '41 days 3 hours','Jessica, thank you! It was a pleasure working on your home. — Sam, Summit Roofing Co.',now() - interval '40 days 1 hour',NULL,false,now() - interval '41 days',now() - interval '40 days',NULL,'posted',false);
OVERRIDING SYSTEM VALUE VALUES (92012,1,910002,'fs-b-sample/reviews/92012','Paul Henderson',5,'Good price, great crew, finished on time. Nothing more you can ask for.',now() - interval '52 days 3 hours','Thanks, Paul! We appreciate you choosing Summit. — Sam, Summit Roofing Co.',now() - interval '51 days 1 hour',NULL,false,now() - interval '52 days',now() - interval '51 days',NULL,'posted',false);
OVERRIDING SYSTEM VALUE VALUES (92101,1,92003,'fs-b-sample/reviews/92101','Laura Jensen',5,'Clearpeak replaced all the siding and windows on our 1970s ranch. The crew protected the landscaping and the house looks brand new.',now() - interval '2 days 5 hours','Thank you, Laura! It was a fun transformation. — Clearpeak Exteriors',now() - interval '2 days',true,now() - interval '2 days',now() - interval '2 days','posted',false);
OVERRIDING SYSTEM VALUE VALUES (92102,1,92004,'fs-b-sample/reviews/92102','Mark Ellison',4,'Good quality siding repair after the hail. Scheduling took a little while but the work was excellent.',now() - interval '6 days 5 hours',NULL,NULL,false,now() - interval '6 days',now() - interval '6 days','draft',false);
OVERRIDING SYSTEM VALUE VALUES (92103,1,92005,'fs-b-sample/reviews/92103','Diane Carver',5,'They cleaned every gutter and found a loose downspout we never noticed. On time and very polite.',now() - interval '3 days 5 hours','Thanks, Diane! See you next fall. — Front Range Gutters',now() - interval '3 days',true,now() - interval '3 days',now() - interval '3 days','posted',false);
OVERRIDING SYSTEM VALUE VALUES (92104,1,92006,'fs-b-sample/reviews/92104','Chris Patel',5,'Seamless gutters installed in one day. Great price and they hauled the old ones away.',now() - interval '9 days 5 hours','Chris, thanks for choosing us! — Front Range Gutters',now() - interval '9 days',false,now() - interval '9 days',now() - interval '9 days','posted',false);
OVERRIDING SYSTEM VALUE VALUES (92105,1,92007,'fs-b-sample/reviews/92105','Monica Hale',5,'Cherry Creek Painting did the whole exterior and trim. Clean lines, great prep work and they left the yard spotless.',now() - interval '1 days 5 hours',NULL,NULL,true,now() - interval '1 days',now() - interval '1 days','draft',false);
OVERRIDING SYSTEM VALUE VALUES (92106,1,92008,'fs-b-sample/reviews/92106','Ray Dominguez',4,'New driveway looks great and drains properly now. Crew was friendly. Took one extra day because of rain.',now() - interval '12 days 5 hours','Thanks, Ray! Enjoy the new driveway. — Red Quarry Concrete & Paving',now() - interval '12 days',false,now() - interval '12 days',now() - interval '12 days','posted',false);
OVERRIDING SYSTEM VALUE VALUES (92107,1,92010,'fs-b-sample/reviews/92107','Sara Lindqvist',5,'Our new cedar fence is beautiful and they finished ahead of schedule. Dana kept us updated the whole time.',now() - interval '4 days 5 hours','Thank you, Sara! Dana will be thrilled to hear it. — Boxelder Fence & Deck',now() - interval '4 days',false,now() - interval '4 days',now() - interval '4 days','posted',false);

